19	// DiscoverReviewSkills walks Claude Code's on-disk plugin layout and user-
20	// level directories looking for review-adjacent invocations. Returns
21	// (nil, nil) when HOME is unreadable or directories are missing — discovery
22	// is best-effort.
23	//
24	// Claude Code exposes three kinds of invocable content per plugin:
25	//   - skills:   <plugin>/skills/<name>/SKILL.md   (YAML frontmatter with name + description)
26	//   - commands: <plugin>/commands/<name>.md       (YAML frontmatter with description; name = filename)
27	//   - agents:   <plugin>/agents/<name>.md         (YAML frontmatter with description; name = filename)
28	//
29	// All three are walked because users invoke them via the same slash-prefix
30	// syntax (`/plugin:name`) and any of them can be a review tool. The
31	// pr-review-toolkit plugin, for example, ships its review skills as
32	// commands/agents (not skills/), and was silently missed by a skills-only
33	// walker.
34	//
35	//nolint:unparam // error return is part of SkillDiscoverer contract; future implementations may report hard failures
36	func (c *ClaudeCodeAgent) DiscoverReviewSkills(ctx context.Context) ([]agent.DiscoveredSkill, error) {
37		home, err := os.UserHomeDir()
38		if err != nil {
39			logging.Debug(ctx, "claude-code discovery: UserHomeDir failed", slog.String("error", err.Error()))
40			return nil, nil
41		}
42	
43		var found []agent.DiscoveredSkill
44		found = append(found, scanPluginCache(ctx, filepath.Join(home, ".claude", "plugins", "cache"))...)
45		found = append(found, scanUserSkills(ctx, filepath.Join(home, ".claude", "skills"))...)
46		found = append(found, scanFlatMarkdownDir(ctx, filepath.Join(home, ".claude", "commands"), "")...)
47		found = append(found, scanFlatMarkdownDir(ctx, filepath.Join(home, ".claude", "agents"), "")...)
48		if len(found) == 0 {
49			return nil, nil
50		}
51		return found, nil
52	}
