54	// scanPluginCache walks <root>/<marketplace>/<plugin>/<version>/{skills,commands,agents}/
55	// One plugin can contribute through any or all three directories.
56	//
57	// Multiple version directories per plugin are common after upgrades. Walking
58	// every version produces duplicate skills (same invocation name, same
59	// description) — confusing in the picker and wasteful in the prompt. We pick
60	// a single version per plugin via pickLatestVersion: prefer valid semver
61	// (highest), fall back to lexicographic max.
62	func scanPluginCache(ctx context.Context, root string) []agent.DiscoveredSkill {
63		entries, err := os.ReadDir(root)
64		if err != nil {
65			logging.Debug(ctx, "claude-code discovery: plugin cache unreadable",
66				slog.String("root", root), slog.String("error", err.Error()))
67			return nil
68		}
69		var found []agent.DiscoveredSkill
70		for _, marketEntry := range entries {
71			if !marketEntry.IsDir() {
72				continue
73			}
74			marketRoot := filepath.Join(root, marketEntry.Name())
75			pluginEntries, err := os.ReadDir(marketRoot)
76			if err != nil {
77				continue
78			}
79			for _, pluginEntry := range pluginEntries {
80				if !pluginEntry.IsDir() {
81					continue
82				}
83				pluginName := pluginEntry.Name()
84				pluginRoot := filepath.Join(marketRoot, pluginName)
85				versionEntries, err := os.ReadDir(pluginRoot)
86				if err != nil {
87					continue
88				}
89				versionDir, ok := pickLatestVersion(versionEntries)
90				if !ok {
91					continue
92				}
93				versionRoot := filepath.Join(pluginRoot, versionDir)
94				found = append(found, readSkillsDir(ctx, filepath.Join(versionRoot, "skills"), pluginName)...)
95				found = append(found, scanFlatMarkdownDir(ctx, filepath.Join(versionRoot, "commands"), pluginName)...)
96				found = append(found, scanFlatMarkdownDir(ctx, filepath.Join(versionRoot, "agents"), pluginName)...)
97			}
98		}
99		return found
100	}
