102	// pickLatestVersion returns the name of the "newest" version directory among
103	// entries. Strategy:
104	//
105	//   - If any entry name parses as semver (with or without a leading "v"), pick
106	//     the highest semver among those that parse. Non-semver entries are
107	//     ignored when at least one semver entry exists.
108	//   - Otherwise, fall back to the lexicographic max of all directory names.
109	//     This handles the "unknown" sentinel some plugins ship and one-off names.
110	//
111	// Returns ("", false) if no usable directory entry exists.
112	func pickLatestVersion(entries []os.DirEntry) (string, bool) {
113		var dirs []string
114		for _, e := range entries {
115			if e.IsDir() {
116				dirs = append(dirs, e.Name())
117			}
118		}
119		if len(dirs) == 0 {
120			return "", false
121		}
122		var semverDirs []string
123		for _, d := range dirs {
124			if semver.IsValid(semverWithV(d)) {
125				semverDirs = append(semverDirs, d)
126			}
127		}
128		if len(semverDirs) > 0 {
129			sort.Slice(semverDirs, func(i, j int) bool {
130				return semver.Compare(semverWithV(semverDirs[i]), semverWithV(semverDirs[j])) > 0
131			})
132			return semverDirs[0], true
133		}
134		sort.Sort(sort.Reverse(sort.StringSlice(dirs)))
135		return dirs[0], true
136	}
137	
138	// semverWithV ensures a version string has the "v" prefix that
139	// golang.org/x/mod/semver requires. Plugin version dirs are usually bare
140	// (e.g. "0.1.0"), but we tolerate either form.
141	func semverWithV(s string) string {
142		if strings.HasPrefix(s, "v") {
143			return s
144		}
145		return "v" + s
146	}
