153	// readSkillsDir reads each skill subdirectory's SKILL.md, parses frontmatter,
154	// and emits a DiscoveredSkill if Matches() returns true.
155	func readSkillsDir(ctx context.Context, dir, pluginName string) []agent.DiscoveredSkill {
156		entries, err := os.ReadDir(dir)
157		if err != nil {
158			return nil
159		}
160		var found []agent.DiscoveredSkill
161		for _, skillEntry := range entries {
162			if !skillEntry.IsDir() {
163				continue
164			}
165			skillDir := filepath.Join(dir, skillEntry.Name())
166			skillFile := filepath.Join(skillDir, "SKILL.md")
167			data, err := os.ReadFile(skillFile) //nolint:gosec // G304: skillFile is constructed from a ReadDir walk under HOME, not user input
168			if err != nil {
169				continue
170			}
171			name, description, parseErr := parseSkillFrontmatter(data)
172			if parseErr != nil {
173				logging.Debug(ctx, "claude-code discovery: skipping malformed SKILL.md",
174					slog.String("path", skillFile), slog.String("error", parseErr.Error()))
175				continue
176			}
177			if name == "" {
178				name = skillEntry.Name()
179			}
180			invocation := invocationName(name, pluginName)
181			if !skilldiscovery.Matches(invocation, description) {
182				continue
183			}
184			found = append(found, agent.DiscoveredSkill{
185				Name:        invocation,
186				Description: description,
187				SourcePath:  skillFile,
188			})
189		}
190		return found
191	}
