193	// scanFlatMarkdownDir reads *.md files directly under dir (no nesting), parses
194	// their YAML frontmatter for `description:`, and derives the invocation name
195	// from the filename (stripping the .md suffix). Used for both plugin
196	// commands/agents and user-level ~/.claude/commands and ~/.claude/agents.
197	//
198	// Frontmatter shape differs from SKILL.md — no `name:` field, so the
199	// filename is the source of truth for the invocation name.
200	func scanFlatMarkdownDir(ctx context.Context, dir, pluginName string) []agent.DiscoveredSkill {
201		entries, err := os.ReadDir(dir)
202		if err != nil {
203			return nil
204		}
205		var found []agent.DiscoveredSkill
206		for _, entry := range entries {
207			if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".md") {
208				continue
209			}
210			baseName := strings.TrimSuffix(entry.Name(), ".md")
211			if strings.EqualFold(baseName, "README") {
212				continue
213			}
214			filePath := filepath.Join(dir, entry.Name())
215			data, err := os.ReadFile(filePath) //nolint:gosec // G304: filePath is constructed from a ReadDir walk under HOME, not user input
216			if err != nil {
217				continue
218			}
219			_, description, parseErr := parseSkillFrontmatter(data)
220			if parseErr != nil {
221				logging.Debug(ctx, "claude-code discovery: skipping malformed command/agent",
222					slog.String("path", filePath), slog.String("error", parseErr.Error()))
223				continue
224			}
225			invocation := invocationName(baseName, pluginName)
226			if !skilldiscovery.Matches(invocation, description) {
227				continue
228			}
229			found = append(found, agent.DiscoveredSkill{
230				Name:        invocation,
231				Description: description,
232				SourcePath:  filePath,
233			})
234		}
235		return found
236	}
