238	// invocationName builds the slash-prefixed invocation form. Plugin-prefixed
239	// names use "/plugin:name"; bare names use "/name".
240	func invocationName(name, pluginName string) string {
241		if pluginName == "" {
242			return "/" + name
243		}
244		return "/" + pluginName + ":" + name
245	}
246	
247	// parseSkillFrontmatter extracts `name:` and `description:` from a minimal
248	// YAML frontmatter block. Purpose-built for the tiny subset of YAML these
249	// SKILL.md / command / agent files actually use.
250	//
251	// Trims surrounding double-quotes from values so `description: "foo bar"`
252	// is returned as `foo bar` — the command/agent frontmatter quotes values;
253	// SKILL.md files usually don't.
254	func parseSkillFrontmatter(data []byte) (name, description string, err error) {
255		s := string(data)
256		if !strings.HasPrefix(s, "---\n") && !strings.HasPrefix(s, "---\r\n") {
257			return "", "", errors.New("no frontmatter delimiter")
258		}
259		body := strings.TrimPrefix(strings.TrimPrefix(s, "---\r\n"), "---\n")
260		end := strings.Index(body, "\n---")
261		if end < 0 {
262			return "", "", errors.New("no closing frontmatter delimiter")
263		}
264		for _, line := range strings.Split(body[:end], "\n") {
265			line = strings.TrimSpace(line)
266			switch {
267			case strings.HasPrefix(line, "name:"):
268				name = strings.Trim(strings.TrimSpace(strings.TrimPrefix(line, "name:")), `"`)
269			case strings.HasPrefix(line, "description:"):
270				description = strings.Trim(strings.TrimSpace(strings.TrimPrefix(line, "description:")), `"`)
271			}
272		}
273		return name, description, nil
274	}
